@reference "../../app/globals.css";

/* =========================================
   Hexagon Grid Core Logic
   ========================================= */

.hex-grid-container {
  display: flex;
  justify-content: center;
  perspective: 1000px;
  width: 100%;
}

.hex-grid {
  display: flex;
  flex-wrap: wrap;
  width: calc((var(--hex-width) + var(--hex-gap)) * 4);
  padding: calc(var(--hex-margin-y) * -1) 0;
}

/* =========================================
   Hexagon Shape, Structure & Depth
   ========================================= */
.hex {
  width: var(--hex-width);
  height: var(--hex-height);
  margin: var(--hex-margin-y) var(--hex-margin-x);
  position: relative;
  cursor: pointer;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.4));
  transform: translateY(0);
  transition:
    filter 0.5s cubic-bezier(0.25, 1, 0.5, 1),
    transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);
}

.hex:nth-child(7n + 5) {
  margin-left: calc((var(--hex-width) / 2) + var(--hex-gap));
}

.hex-shape {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  @apply bg-slate-900;
}

.hex-shape::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at 50% 50%,
    transparent 40%,
    rgba(0, 0, 0, 0.8) 120%
  );
  pointer-events: none;
  z-index: 1;
  transition: opacity 0.5s ease;
}

/* =========================================
   Immersive Interactions
   ========================================= */

.hex:focus-visible {
  outline: none;
}

.hex::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: rgba(255, 255, 255, 0.9);
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  z-index: -1;
  opacity: 0;
  transform: scale(1);
  transition:
    opacity 0.4s ease,
    transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}

.hex:focus-visible::before {
  opacity: 1;
  transform: scale(1.05);
}

.hex:hover,
.hex:focus-within {
  z-index: 10;
  transform: translateY(-6px);
  filter: drop-shadow(0 20px 25px rgba(0, 0, 0, 0.7));
}

.hex:hover .hex-shape::after,
.hex:focus-within .hex-shape::after {
  opacity: 0;
}

.hex img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  filter: grayscale(70%) brightness(0.7) contrast(1.1);
  transform: scale(1.02);
  backface-visibility: hidden;
  will-change: transform;
  transition:
    transform 0.6s cubic-bezier(0.25, 1, 0.5, 1),
    filter 0.6s ease;
}

.hex:hover img,
.hex:focus-visible img {
  transform: scale(1.15);
  filter: grayscale(0%) brightness(1.05) contrast(1.05);
}

/* =========================================
   Caption Overlay
   ========================================= */
.hex-caption {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.95) 0%,
    rgba(0, 0, 0, 0.4) 50%,
    rgba(0, 0, 0, 0) 100%
  );
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding: 0 20px 70px 20px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.hex-caption h3 {
  color: #ffffff;
  font-size: 1.4rem;
  font-weight: 600;
  margin: 0 0 6px 0;
  letter-spacing: 0.5px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8);
  transform: translateY(15px);
  transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}

.hex-caption p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.7rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin: 0;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
  transform: translateY(15px);
  transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}

.hex:hover .hex-caption,
.hex:focus-visible .hex-caption {
  opacity: 1;
}

.hex:hover .hex-caption h3,
.hex:focus-visible .hex-caption h3 {
  transform: translateY(0);
}

.hex:hover .hex-caption p,
.hex:focus-visible .hex-caption p {
  transform: translateY(0);
  transition-delay: 0.05s;
}

/* =========================================
   Responsive Layouts
   ========================================= */
@media (max-width: 1024px) {
  .hex-grid {
    width: calc((var(--hex-width) + var(--hex-gap)) * 3);
  }
  .hex:nth-child(7n + 5) {
    margin-left: var(--hex-margin-x);
  }
  .hex:nth-child(5n + 4) {
    margin-left: calc((var(--hex-width) / 2) + var(--hex-gap));
  }
}

@media (max-width: 768px) {
  .hex-grid {
    width: calc((var(--hex-width) + var(--hex-gap)) * 2);
  }
  .hex:nth-child(5n + 4) {
    margin-left: var(--hex-margin-x);
  }
  .hex:nth-child(3n + 3) {
    margin-left: calc((var(--hex-width) / 2) + var(--hex-gap));
  }
}

@media (max-width: 550px) {
  .hex-grid {
    width: calc((var(--hex-width) * 1.5) + (var(--hex-gap) * 1.5));
  }
  .hex:nth-child(3n + 3) {
    margin-left: var(--hex-margin-x);
  }
  .hex:nth-child(even) {
    margin-left: calc((var(--hex-width) / 2) + var(--hex-gap));
  }
}

'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import './hexagon-grid.css';

export interface HexGridProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: number; // Size in pixels
  gap?: number; // Gap in pixels
}

export const HexGrid = React.forwardRef<HTMLDivElement, HexGridProps>(
  ({ className, size = 220, gap = 16, children, ...props }, ref) => {
    return (
      <div className={cn('hex-grid-container', className)} ref={ref} {...props}>
        <div
          className='hex-grid'
          style={
            {
              '--hex-width': `${size}px`,
              '--hex-gap': `${gap}px`,
              '--sqrt3': '1.73205',
              '--hex-height': `calc(var(--hex-width) * 2 / var(--sqrt3))`,
              '--hex-margin-x': `calc(var(--hex-gap) / 2)`,
              '--hex-margin-y': `calc((var(--sqrt3) / 4 * var(--hex-gap)) - (0.125 * var(--hex-height)))`,
            } as React.CSSProperties
          }
        >
          {children}
        </div>
      </div>
    );
  }
);
HexGrid.displayName = 'HexGrid';

export interface HexagonProps extends React.HTMLAttributes<HTMLDivElement> {
  imageSrc: string;
  imageAlt?: string;
  title?: React.ReactNode;
  subtitle?: React.ReactNode;
}

export const Hexagon = React.forwardRef<HTMLDivElement, HexagonProps>(
  (
    {
      className,
      imageSrc,
      imageAlt = 'Hexagon image',
      title,
      subtitle,
      ...props
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        className={cn('hex', className)}
        tabIndex={0}
        role='button'
        {...props}
      >
        <div className='hex-shape'>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={imageSrc} alt={imageAlt} />
          {(title || subtitle) && (
            <div className='hex-caption'>
              {title && <h3>{title}</h3>}
              {subtitle && <p>{subtitle}</p>}
            </div>
          )}
        </div>
      </div>
    );
  }
);
Hexagon.displayName = 'Hexagon';
